BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (400::BIGINT, 'Este curso no lo he disfrutado para nada. El profe es buena gente, pero no está hecho para ser profesor. Piensa que todo es súper obvio. El curso está casi que hecho en su totalidad por el asistente. Sus exámenes son demasiado rudos para lo que él explica en clase. Léase el libro!!'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2026-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'f43f276a52affb835ad89d68f2e72bd5b1014905470ba291e714ca28f05753ec'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, 'En general buen profe, usted tiene que aprender a usar SVerilog por su cuenta, gran parte del trabajo lo hace el asistente, no es el mejor pero se la juega'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2026-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'fc9f5d3fa6d758e59c93c055357de07cfc0ed199fdf64e8983927f0c57977587'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, 'Se desentendió mucho del curso, faltó a muchas clases y dejó que el asistente hiciera casi todo, hasta darnos clases a veces. Hay que poner mucho esfuerzo propio para entender porque los temas son muy nuevos a veces. Los proyectos son largos entonces se tienen que hacer con tiempo, no dias antes'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2026-04-28T00:00:00+00:00'::TIMESTAMPTZ, '48f43cdb6d8a258c2919302a9b964fdf1208ecf85e5debfee4133d9bc2c212d7'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, 'Es flexible con las entregas y explica relativamente bien, solo que piensa que las cosas son muy obvias. Enseña parcialmente S.verilog, trate de repasar la progra del libro, los proyectos son interesantes pero algo demandantes. Igual lo recomiendo. Todo lo califica el asistente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '4364e1eb8514bcf525155c83064361ec20d5e0609a4f58ffc41d33a203e6bbd6'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, '. Absolutamente todo lo hizo el asistente, no él'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2025-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'e3118672d776996344afaef39af2e6a69d4fc49e74a39827ff2bdccc7996cf49'::TEXT, ARRAY[1294, 1307, 1359, 1334, 1310, 1295]::BIGINT[]),
    (400::BIGINT, 'El profe llega, da la clase y se desentiende del curso. Nunca explica las tareas que se asignan lo cual hace todo más complicado. Absolutamente todo lo hizo el asistente, no él. La estrategia sería estudiar del libro y si no entendió algo ir a consulta xq las clases no ayudan mucho.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '37ff9f2dc3be45420acb66f7068c9dec8e8c7cd1f7c7c0688bd3222db7c82176'::TEXT, ARRAY[3980]::BIGINT[]),
    (400::BIGINT, 'Es la opción correcta para llevar el curso ya que enseña SystemVerilog y eso es muy importante en el resto de la carrera. Además se aprende muchísimo, ayuda bastante y es muy amable.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2023-11-11T00:00:00+00:00'::TIMESTAMPTZ, '65c90a28d51315730fc73a9945a1f141337ac08bedab671f10369663a6fd03f4'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, 'Sinceramente no entiendo porqué tantos comentarios negativos. El profesor es muy buena persona, muy dispuesto a ayudar y enseña mucho del curso (Verilog es la biblia de Electrónica y Computadores). Deja bastantes tareas que ayudan a llevar la materia al día, hacer práctica y además son puntos extra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Da crédito extra']::TEXT[], '2023-03-03T00:00:00+00:00'::TIMESTAMPTZ, 'ac043febfcaf10894f99b0f1de13dbae7040d9dae69607011919f030399b8339'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, 'Da puntos extra ( recomiendo hacerlos) Los examenes son ejercicios del libro y ayuda para los proyectos. Las clases son toque pesadas pero el profe intenta hacerlas ligeras metiendo practica dentro de la clase. Lo recomiendo mucho ya que se aprende mucho y es super buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'bef494c37858538609630a1c688ff2e9a3a23bd98703f86db7f19e09a69c8806'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, 'Hace el curso mil veces más dificil de lo que ya es, no hace ejercicios en clase y los proyectos son imposibles, hay que aprender a usar Verilog y Vivado por cuenta de cada uno porque no lo explica en clase y se necesita para los proyectos. Aveces da mas tiempo para los proyectos.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-22T00:00:00+00:00'::TIMESTAMPTZ, '1332638979caa1f7b66891155e7cb08d9247682e55f2075b9a784d8c908c3d0e'::TEXT, ARRAY[1282]::BIGINT[]),
    (400::BIGINT, 'que se pensione, no sabe enseñar'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'a6f68c008a4e0e25a209f005f7303519803a52d5ccbafad96b0dffcea00444c9'::TEXT, ARRAY[1267]::BIGINT[]),
    (400::BIGINT, 'En la clase no se le entiende nada, para las evaluaciones muy comprensivo y era muy bueno con la retroalimentación, sin embargo dejé de ir a las clases al final del semestre por que estaba perdiendo mi tiempo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'aa15f93e4bfa4079cfbe389418d5ee4df1505f8c6af6e4c375ddb1c38d447ef6'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'Con todo respeto, por profes como este es que la escuela de electro tiene tan lama fama. Es MUY mal profesor, no sabe explicar, no sabe escribir notas claras y los exámenes son como de maestría (y como si el explicara bien en las clases). Hágase un favor y no matricule con él'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd8576a52384c107f7010deb49e05edb073cc7da91ba48c9aa323345144aa1c7e'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'el profe no se le entiende, no explica bien'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '7843ba9e18ddf08d830448e70629a575223276b9b228e03dbdb250bafd0e4b9d'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'Hace el curso demasiado difícil. Al primer examen uno no sabe donde está parado, ya para los otros todo es electro y lo normal. El mae explica bien teoría, pero para pasar haga toda la practica del Razavi. Y di mae, RazaviRazaviRazaviRazavi'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'f5a84258cfbbb398a43f4aa725e8b12a63e6118450f27f8150efb5f570866be3'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'Aunque hace el curso más difícil que otros profesores, se aprende mucho más, si vas a consulta ayuda y deja un proyecto en ltspice sencillo para ayudar con la nota final.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'd0bff3d6b29b10ca67354f04af0174c8cda7a8749694319046a211c88649f0b3'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'No enseña'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '45a0a646fd9983aa1661833ec3a2bf821bb96c649c2969e743cd02af4b6c54d4'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'El curso se pasa bien si usted estudia por su lado pero olvídese de la ayuda del profesor. Él es bueno pero no para enseñar y complica el curso.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-04T00:00:00+00:00'::TIMESTAMPTZ, 'ca4fbe7808ef200721b45ba97d1a47352bbb6bb2b5f34b05fd5eacfd43806cb1'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'No recomendable para elementos activos, él puede ser catedrático y lo que quiera, pero como profesor no es muy bueno para mi gusto, da la materia como si uno supiera algo antes y no le importa mucho si quedó clara.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'b468a84be4ead789fe3ca0d359ca0832f2dc4d18254e1899ae1cd7db203ee07d'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'Sabe mucho sin embargo no sabe dar clases, es algo burlista con el estudiante, hay que estudiar solo, y basándose en ejercicios del Razavi y Pedro Julián. Las tutorías están hechas desde el 2011 por lo que son muy desactualizadas según la diferencia de profesores desde ese año al actual.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'a2f97bc02042df0e72ee853761760f3f2f19ad03953d0507cfdc87b39a074be7'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'Es un curso fácil pero lo hace difícil. A veces va muy rápido, no explica muy claro y aveces cuesta mucho entenderle. Sabe mucho pero le hace falta un curso de pedagogía para enseñar bien. Toda la clase es el libro del Razavi. Asistir a las tutorías ayudan demasiado'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '0d0d25bfbb4918f4867356d6feaf02c3a9e5c884dc6a649c17723d635439dc8b'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'Me pareció muy duro pero no fatal. Hay que poner mucho de parte de uno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'fdb4e6cfa8bb34cc407bcb99ba315fff1d90c1f88c0ebbef170b3765b232c755'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'Es un predicador del Razavi. Explica bien, pero deja muchos detalles de lado. Si usted no entiende, él le explica bien en consulta. El curso lo pasa usted con el Razavi y un buen formulario. Ruegue porque en la Cátedra no esté Rivas. En general, no es mal profe, pero sí le falta mejorar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '4b7e4f9658024214846ef5c68f446547dd0bf326ea9bba1719a7adfe71ebd97d'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'El curso de activos con el fue rudisisimo la verdad, pero aprendi bastante. El Razavi es como la biblia de el asi que si no se la leyo antes de ir a clase va a mamar toda la clase y el curso. El mae sabe muchisimo pero este curso era muy basico para el y se puso creativo'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'a266150471fb5259966895775b905724ed47138a344e5cf7bddbb731a50897bd'::TEXT, ARRAY[1270]::BIGINT[]),
    (400::BIGINT, 'Malo con M de cabron'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-27T00:00:00+00:00'::TIMESTAMPTZ, 'e678f07f3264aaa4de6fbbd1d4b62bddb7bd599ebb6fbda5ac5773b5e2040ea9'::TEXT, ARRAY[1294, 1307, 1359, 1334, 1310, 1295]::BIGINT[]),
    (400::BIGINT, 'El mejor para el curso. Leer el Razavi antes de clases, practicar de ahí mismo y listo. Forma ingenieros.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '76581bd0581e8c3fe6047bd31e1a7aaa50465d64c8ecc1f0e0e089b21907567f'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'Va muy rápido dando la clase (o escriba o se suicida). No da chance de copiar porque borra. El inicio del curso es muy difícil porque todos vienen mal de activos y al profe le da igual.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, '26189339199226f864fe15051d4c5577c513be4e72ae3e64203c68666c8f6fa0'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'M;alo'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-27T00:00:00+00:00'::TIMESTAMPTZ, '2ecce79bbbf4bec8e71c239147380fd0901e7bf1329b1619167190b8ba8975e5'::TEXT, ARRAY[1276]::BIGINT[]),
    (400::BIGINT, 'No sirve'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'cc9cb4c5ba32866a194f8d1c51f66523c0921ef21658f750acfd4ac2e7533184'::TEXT, ARRAY[1390, 1374, 1280, 1271, 3034, 3033]::BIGINT[]),
    (400::BIGINT, 'Otro de los "yo soy doctor" de electrónica, manipulador y juega de muy recto. Caigale bien y ganaste el curso,'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2017-08-10T00:00:00+00:00'::TIMESTAMPTZ, '1fedeb34d641388c7753537b2e5886b98cab541597154a8bbdf09d02e7a45b05'::TEXT, ARRAY[1290]::BIGINT[]),
    (400::BIGINT, 'Al principio cuesta agarrarle el ritmo pero si uno logra concentrarse y acostumbrase se aprende mucho. El mejor profesor para el curso y creo que el profe mas crack que he tenido'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '182e891b36df66bb4731886e9da9a595f8d4287d96ea560db116a3f8aafb2bb3'::TEXT, ARRAY[1279]::BIGINT[]),
    (400::BIGINT, 'Se aprende la razón de las cosas, no solo "funciona por que si". Es conciso con lo que quiere de uno, de lo mejor de la escuela.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '882104c3654e797dcd998bf4a52ea9902052c0ac62c25b64c9cab0909c1c9bf5'::TEXT, ARRAY[1303]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
